meta.script:
// This waits for all the external ressources (including ABTasty tag) to load before executing the callback function.
window.addEventListener('load', function () {
  if(!window.ABTasty) {
    // AB Tasty tag is not loaded so exit.
    return
  }

  if (window.ABTasty.eventState?.['consentValid']?.status === 'complete') {
    updateShopifyDataForWebPixel();
  } else {
    window.addEventListener('abtasty_consentValid', () => {
      updateShopifyDataForWebPixel();
    });
  }


  async function waitForVisitorId(maxRetries = 5, delayMs = 500) {
    for (let i = 0; i < maxRetries; i++) {
      const visitorId = ABTasty.api.v1.getValue('visitorId')
      if (visitorId) {
        return visitorId;
      }
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
  }


  async function updateShopifyDataForWebPixel() {
    const STORAGE_KEY = 'ABTastyShopify';
    const consentReady = ABTasty.consentReady;
    const shouldHandleSubdomain = "false" === "true";

    if(!consentReady) {
      if(shouldHandleSubdomain) {
        await cookieStore.delete(STORAGE_KEY);
      }
      return localStorage.removeItem(STORAGE_KEY);
    }

    const visitorId = await waitForVisitorId(5, 500);

    if (!visitorId) {
      console.error('[AB Tasty] Unable to get AB Tasty visitorID after 5 retry');
      return;
    }

    const ABTastyData = {
      identifier: "1ee7c0920d1da2a518b6b72411c0ce6a",
      campaigns: ABTasty.getCampaignHistory(),
      visitorId: visitorId,
      accountId: ABTasty.getAccountSettings().id,
      consent: ABTasty.consentReady,
    };

    if (shouldHandleSubdomain) {
      await cookieStore.set({
        name: STORAGE_KEY,
        value: JSON.stringify(ABTastyData),
        expires: Date.now() + 1 * 24 * 60 * 60 * 1000, // 1 day
        domain: window.location.hostname,
      });
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(ABTastyData));
  }
});

